function check(name,run,target){test(`Projects: ${name}`,async()=>{const h=harness(target);try{await run(h);}finally{h.cleanup();}});}
function nodes(tree,name){const out=[];const visit=n=>{if(!n||typeof n!=='object')return;if(Array.isArray(n)){n.forEach(visit);return;}if((typeof n.type==='function'?n.type.name:n.type)===name)out.push(n);visit(n.props?.children);};visit(tree);return out;}
