check('register request preserves limit30 and exact search/status parameters',async h=>{h.query('search=Synthetic+%26+Client&status=active');h.render();await h.api().loadList();assert.equal(h.requests[0].url,'/api/projects?limit=30&search=Synthetic+%26+Client&status=active');assert.equal(h.state('state').rows[0].id,row.id);assert.equal(h.requests[0].options.cache,'no-store');});
check('register metadata and role-scoped summary load separately from list filters',async h=>{h.render();await h.api().loadMeta();assert.deepEqual(h.requests.map(r=>r.url),['/api/projects/meta','/api/projects/summary']);assert.deepEqual(h.state('meta'),meta);assert.deepEqual(h.state('summary'),summary);h.query('status=planned');h.render();await h.api().loadList();assert.equal(h.requests.length,3);});
check('direct pages state follows cursors, removes cross-page duplicate IDs and keeps native amounts',async h=>{h.query('pages=2');h.render();h.response(url=>ok(url.includes('cursor=')?{items:[row,{...row,id:'syn-bdt',currency:'BDT',contract_value:'1000'}],next_cursor:null}:{items:[row],next_cursor:'cursor / 2'}));await h.api().loadList();assert.deepEqual(h.requests.map(r=>r.url),['/api/projects?limit=30','/api/projects?limit=30&cursor=cursor+%2F+2']);assert.deepEqual(h.state('state').rows.map(r=>[r.id,r.currency,r.contract_value]),[['syn-project','USD','125.50'],['syn-bdt','BDT','1000']]);});
