check('latest filter request wins over a late older success or error',async h=>{h.render();let resolve;h.response(()=>new Promise(r=>{resolve=r;}));const older=h.api().loadList();h.query('search=newer');h.render();h.response(()=>ok({items:[{...row,id:'newer'}],next_cursor:null}));await h.api().loadList();resolve(ok({items:[row],next_cursor:null}));await older;assert.equal(h.state('state').rows[0].id,'newer');});
