const credentialValues={name:'Synthetic fixture only',credential_type:'login',environment:'development',username:'synthetic@example.invalid',secret:'SYNTHETIC-NOT-A-SECRET',url:'https://example.invalid',notes:'Synthetic fixture',access_level:'team'};
