for(const[mode,suffix,fn,values,method,url,body]of [
 ['milestone','/milestones/new','createMilestone',{title:'Milestone',description:'',due_date:''},'POST','/milestones',{title:'Milestone',description:null,due_date:null}],
 ['milestone edit','/milestones/'+milestone.id+'/edit','updateMilestone',{title:'Updated milestone',description:'Details',due_date:'2026-11-01'},'PATCH','/milestones/'+milestone.id,{title:'Updated milestone',description:'Details',due_date:'2026-11-01'}],
 ['task','/tasks/new','createTask',taskValues,'POST','/tasks',{title:'Synthetic task',description:null,milestone_id:null,priority:'high',assignee_employee_id:null,planned_start_date:null,due_date:'2026-11-01',estimated_minutes:68}],
 ['task edit','/tasks/'+task.id+'/edit','updateTask',taskValues,'PATCH','/tasks/'+task.id,{title:'Synthetic task',description:null,milestone_id:null,priority:'high',assignee_employee_id:null,planned_start_date:null,due_date:'2026-11-01',estimated_minutes:68}],
 ['work update','/tasks/'+task.id+'/progress','updateProgress',{progress:55,note:'Synthetic historical update',status:'',time_hours:'0.125'},'POST','/tasks/'+task.id+'/progress',{progress_percent:55,note:'Synthetic historical update',status:null,time_spent_minutes:8}],
 ['document metadata','/documents/'+doc.id+'/edit','updateDocument',{title:'  Updated title ',document_type:' technical ',notes:' '},'PATCH','/documents/'+doc.id,{title:'Updated title',document_type:'technical',notes:null}],
 ['credential create','/credentials/new','createCredential',credentialValues,'POST','/credentials',credentialValues],
 ['credential edit blank secret','/credentials/'+credential.id+'/edit','updateCredential',{...credentialValues,secret:''},'PATCH','/credentials/'+credential.id,Object.fromEntries(Object.entries(credentialValues).filter(([key])=>key!=='secret'))],
]){
 check(`${mode} sends exact original request payload and replaces editor after commit`,async h=>{readyDetail(h,suffix);await h.api()[fn](values);assert.equal(h.requests.length,1);assert.equal(h.requests[0].url,'/api/projects/'+project.id+url);assert.equal(h.requests[0].options.method,method);assert.deepEqual(JSON.parse(h.requests[0].options.body),body);assert.equal(h.state('documentCommitted'),true);assert.equal(h.navigation[0][2].replace,true);},'useProjectWorkspace');
 check(`${mode} rejects repeated pending submit before React rerenders`,async h=>{readyDetail(h,suffix);let resolve;h.response(()=>new Promise(r=>{resolve=r;}));const first=h.api()[fn](values);await h.api()[fn](values);assert.equal(h.requests.length,1);resolve(ok({id:'syn-created'}));await first;},'useProjectWorkspace');
 check(`${mode} validation failure keeps dirty editor available without navigation`,async h=>{readyDetail(h,suffix);h.set('formDirty',true);h.render();h.response(()=>fail(422,'Synthetic validation denied'));await h.api()[fn](values);assert.equal(h.state('documentCommitted'),false);assert.equal(h.state('formDirty'),true);assert.equal(h.state('saving'),false);assert.equal(h.navigation.length,0);assert.equal(h.guardCalls.some(c=>c.kind==='clean'),false);},'useProjectWorkspace');
}
