const editorFile='src/components/projects/project-editors.tsx';
function form(h,name,overrides={}){const props={saving:false,onClose:()=>{},onSave:()=>{},onDirtyChange:()=>{},milestone,tasks:[task],projectDueDate:project.due_date,task,milestones:[milestone],members:[member],credential:null,error:null,project,employees:[employee,otherEmployee],document:doc,...overrides};return{props,render:()=>h.component(editorFile,name,props)};}
for(const[name,field,value]of [['MilestoneEditor','title','Keep milestone'],['EditMilestoneEditor','description','Keep description'],['TaskEditor','title','Keep task'],['EditTaskEditor','due','2026-12-01'],['ProgressEditor','note','Keep update'],['DocumentEditor','title','Keep document'],['CredentialEditor','secret','SYNTHETIC-NOT-A-SECRET'],['TeamEditor','manager',otherEmployee.id],['EditDocumentEditor','notes','Keep notes']])check(`${name} starts clean, marks changed fields dirty, and restored fields clean`,h=>{const dirty=[],f=form(h,name,{onDirtyChange:v=>dirty.push(v)});f.render();effect(h,/onDirtyChange/);assert.equal(dirty.at(-1),false);const initial=h.state(field);h.set(field,value);f.render();effect(h,/onDirtyChange/);assert.equal(dirty.at(-1),true);h.set(field,initial);f.render();effect(h,/onDirtyChange/);assert.equal(dirty.at(-1),false);assert.equal(h.requests.length,0);});
check('completed task can reopen below100 through automatic status without changing historical work payload',h=>{const saved=[],f=form(h,'ProgressEditor',{task:{...task,status:'completed',progress_percent:100},onSave:v=>saved.push(v)});f.render();assert.equal(h.state('status'),'');h.set('progress',65);h.set('note',' Synthetic reopening ');h.set('hours','0.25');const tree=f.render();assert.match(text(tree),/reopen/);tree.props.onSave();assert.deepEqual(saved,[{progress:65,note:'Synthetic reopening',status:'',time_hours:'0.25'}]);});
check('task schedule editing uses hours from original minutes and blocks inverted dates',h=>{const f=form(h,'EditTaskEditor');let tree=f.render();assert.equal(h.state('hours'),'1.5');assert.equal(tree.props.disabled,false);h.set('start','2026-11-10');h.set('due','2026-11-01');tree=f.render();assert.equal(tree.props.disabled,true);assert.match(text(tree),/Due date cannot be before/);});
check('milestone warnings compare only active child tasks and remain advisory',h=>{const f=form(h,'EditMilestoneEditor',{tasks:[task,{...task,id:'completed',status:'completed',due_date:'2099-12-31'}]});f.render();h.set('due','2026-11-01');const tree=f.render();assert.match(text(tree),/2026-11-05/);assert.doesNotMatch(text(tree),/2099/);assert.equal(tree.props.disabled,false);});
for(const[saving,disabled,expected]of [[false,false,1],[true,false,0],[false,true,0]])check(`editor form submission is guarded saving=${saving} invalid=${disabled}`,h=>{let saves=0,cancels=0;const tree=h.component(editorFile,'EditorFrame',{title:'Synthetic form',description:'Synthetic',saving,disabled,onSave:()=>saves++,onClose:()=>cancels++,summary:null,children:null});assert.equal(nodes(tree,'fieldset')[0].props.disabled,saving);const ev={preventDefault(){this.prevented=true;}};tree.props.onSubmit(ev);assert.equal(ev.prevented,true);assert.equal(saves,expected);const cancel=nodes(tree,'button').find(b=>text(b)==='Cancel');assert.equal(cancel.props.disabled,saving);if(!saving)cancel.props.onClick();assert.equal(cancels,saving?0:1);assert.equal(h.requests.length,0);});
