const sharingFile='src/components/project-client-milestone-sharing.tsx';
const sharingRow={...milestone,client_visible:false};
function sharing(h,open=false){return h.component(sharingFile,'ProjectClientMilestoneSharingContent',{projectId:project.id,open,entryHref:'/dashboard/projects/'+project.id+'?tab=notes&sharing=milestones',returnHref:'/dashboard/projects/'+project.id+'?tab=notes'});}
function loadSharingAccess(h){return effect(h,/const controller = lifecycle.current/);}
async function readySharing(h,status='active'){
 h.response(url=>url.endsWith('/workspace')?ok({milestones:[sharingRow]}):ok({...project,status}));
 sharing(h,true);loadSharingAccess(h);await settle();sharing(h,true);await h.api().loadWorkspace();sharing(h,true);return h.state('milestones')[0];
}
