for(const hook of ['useProjectRegister','useProjectCreate','useProjectWorkspace'])check(`${hook} layout unmount suppresses current 401 redirect`,async h=>{h.query('order_id='+order.id);h.render();const pending=[];h.response(()=>new Promise(r=>pending.push(r)));const request=hook==='useProjectWorkspace'?h.api().refresh():hook==='useProjectCreate'?h.api().load():h.api().loadList();h.cleanupLayout();pending.forEach(r=>r(fail(401)));await request;assert.deepEqual(h.navigation,[]);},hook);
check('superseded workspace refresh 401 cannot redirect newer data',async h=>{readyDetail(h);const pending=[];h.response(()=>new Promise(r=>pending.push(r)));const old=h.api().refresh();h.response(h.defaultResponse);await h.api().refresh();pending.forEach(r=>r(fail(401)));await old;assert.deepEqual(h.navigation,[]);assert.equal(h.state('project').id,project.id);},'useProjectWorkspace');
check('tab-dismissed credential reveal 401 cannot redirect or reveal',async h=>{h.query('tab=credentials');readyDetail(h);let resolve;h.response(()=>new Promise(r=>{resolve=r;}));const old=h.api().revealCredential(credential.id);h.query('tab=tasks');h.render();effect(h,/revealsPendingRef.current.clear/);resolve(fail(401));await old;assert.deepEqual(h.navigation,[]);assert.deepEqual(h.state('revealed'),{});},'useProjectWorkspace');
for(const outcome of ['transport','server','malformed-id'])check(`create ${outcome} is uncertain and permits only read-only link recovery`,async h=>{readyCreate(h);h.response(()=>outcome==='transport'?Promise.reject(new Error('Disconnected')):outcome==='server'?fail(503):ok({}));await h.api().createProject();h.render();assert.equal(h.state('unknownWrite'),true);assert.equal(h.state('createdId'),null);await h.api().createProject();assert.equal(h.requests.filter(r=>r.options.method==='POST').length,1);h.response(url=>url.endsWith('/link')?ok({project_id:'saved',project_number:'P-SAVED'}):h.defaultResponse(url,{}));await h.api().load();h.render();assert.equal(h.state('link').project_id,'saved');await h.api().createProject();assert.equal(h.requests.filter(r=>r.options.method==='POST').length,1);},'useProjectCreate');
for(const operation of ['createMilestone','createTask','updateProgress','uploadDocument','createCredential'])check(`${operation} interrupted write cannot send a second POST even after refresh`,async h=>{const suffix=operation==='updateProgress'?'/tasks/'+task.id+'/progress':operation==='createCredential'?'/credentials/new':operation==='createTask'?'/tasks/new':operation==='uploadDocument'?'/documents/new':'/milestones/new';readyDetail(h,suffix);const values=operation==='createMilestone'?{title:'Synthetic',description:'',due_date:''}:operation==='createTask'?taskValues:operation==='updateProgress'?{progress:30,note:'Synthetic work',status:'',time_hours:'1'}:operation==='uploadDocument'?{title:'Synthetic',document_type:'technical',notes:'',file:new File(['synthetic'],'synthetic.txt')}:credentialValues;h.response(()=>Promise.reject(new Error('Disconnected')));await h.api()[operation](values);h.render();assert.equal(h.state('unknownWrite'),true);await h.api()[operation](values);assert.equal(h.requests.filter(r=>r.options.method==='POST').length,1);h.response(h.defaultResponse);await h.api().refresh();h.render();await h.api()[operation](values);assert.equal(h.requests.filter(r=>r.options.method==='POST').length,1);},'useProjectWorkspace');
check('definite validation rejection retains retry after fields are corrected',async h=>{readyDetail(h,'/milestones/new');h.response(()=>fail(422,[{loc:['body','title'],msg:'Required'}]));await h.api().createMilestone({title:'',description:'',due_date:''});assert.equal(h.state('unknownWrite'),false);assert.match(h.state('error'),/title: Required/);h.response(h.defaultResponse);await h.api().createMilestone({title:'Corrected',description:'',due_date:''});assert.equal(h.requests.filter(r=>r.options.method==='POST').length,2);assert.equal(h.state('documentCommitted'),true);},'useProjectWorkspace');
check('register and create remount identity reacts to same-company permission changes',h=>{for(const name of ['ProjectRegisterWorkspace','ProjectCreateWorkspace']){h.permissions(['projects.manage']);const before=h.component(registerFile,name,{}).key;h.permissions(['projects.work']);assert.notEqual(h.component(registerFile,name,{}).key,before);}});
check('committed query change suppresses old list 401 before replacement passive read begins',async h=>{h.render();let resolve;h.response(()=>new Promise(r=>{resolve=r;}));const old=h.api().loadList();h.query('search=changed');h.render();resolve(fail(401));await old;assert.deepEqual(h.navigation,[]);});
check('committed order change suppresses old handoff 401 before passive cleanup',async h=>{h.query('order_id='+order.id);h.render();h.set('meta',meta);h.render();const pending=[];h.response(()=>new Promise(r=>pending.push(r)));effect(h,/setHandoff/);h.query('order_id=next');h.render();pending.forEach(r=>r(fail(401)));await settle();assert.deepEqual(h.navigation,[]);});
check('committed new create order suppresses old setup401 before passive reload',async h=>{h.query('order_id='+order.id);h.render();let resolve;h.response(()=>new Promise(r=>{resolve=r;}));const old=h.api().load();h.query('order_id=next');h.render();resolve(fail(401));await old;assert.deepEqual(h.navigation,[]);},'useProjectCreate');
for(const responseKind of ['malformed-422','timeout-408','server-500'])check(`${responseKind} is not proof a milestone write was rejected`,async h=>{readyDetail(h,'/milestones/new');h.response(()=>responseKind==='malformed-422'?{...ok(null),ok:false,status:422}:fail(responseKind==='timeout-408'?408:500));await h.api().createMilestone({title:'Synthetic',description:'',due_date:''});h.render();assert.equal(h.state('unknownWrite'),true);await h.api().createMilestone({title:'Synthetic',description:'',due_date:''});assert.equal(h.requests.filter(r=>r.options.method==='POST').length,1);},'useProjectWorkspace');

for(const identity of ['membership','role'])check(`register and create remount on same-company ${identity} replacement`,h=>{for(const name of ['ProjectRegisterWorkspace','ProjectCreateWorkspace']){h[identity]('first');const before=h.component(registerFile,name,{}).key;h[identity]('second');assert.notEqual(h.component(registerFile,name,{}).key,before);}});

const projectDetailsValues={name:'  আন্তর্জাতিক delivery  ',priority:'high',planned_start_date:'2026-10-30',due_date:'2026-12-31',description:'  Project description  ',notes:'  Internal handoff  '};
check('project details direct route is a distinct overview-scoped editor',h=>{const model=h.load(path.join(root,'src/components/projects/project-model.ts'));assert.deepEqual(model.parseProjectWorkspaceRoute('/dashboard/projects/syn-project/edit','syn-project'),{kind:'editor',section:'overview',editorMode:'project'});for(const suffix of ['/edit/extra','/edit/id/edit'])assert.deepEqual(model.parseProjectWorkspaceRoute('/dashboard/projects/syn-project'+suffix,'syn-project'),{kind:'invalid'});});
check('global manager details PATCH retains exact six fields and Unicode without financial/team/status changes',async h=>{readyDetail(h,'/edit');await h.api().updateProjectDetails(projectDetailsValues);assert.equal(h.requests[0].url,'/api/projects/syn-project');assert.equal(h.requests[0].options.method,'PATCH');assert.deepEqual(JSON.parse(h.requests[0].options.body),{name:'আন্তর্জাতিক delivery',priority:'high',planned_start_date:'2026-10-30',due_date:'2026-12-31',description:'Project description',notes:'Internal handoff'});assert.equal(h.state('documentCommitted'),true);assert.equal(h.navigation[0][2].replace,true);},'useProjectWorkspace');
check('project details clears optional fields with explicit nulls',async h=>{readyDetail(h,'/edit');await h.api().updateProjectDetails({...projectDetailsValues,planned_start_date:'',due_date:'',description:'  ',notes:''});assert.deepEqual(JSON.parse(h.requests[0].options.body),{name:'আন্তর্জাতিক delivery',priority:'high',planned_start_date:null,due_date:null,description:null,notes:null});},'useProjectWorkspace');
for(const [name,patch]of [['assigned project manager only',{project:{...project,access:{...project.access,can_manage_project:false,is_project_manager:true}}}],['authoritative metadata denies management',{meta:{...meta,can_manage_projects:false}}],['completed project',{project:{...project,status:'completed'}}],['cancelled project',{project:{...project,status:'cancelled'}}],['overview tab inaccessible',{project:{...project,access:{...project.access,allowed_tabs:['tasks']}}}]])check(`details editor refuses ${name} before mutation`,async h=>{readyDetail(h,'/edit',patch);assert.equal(h.api().editorAllowed,false);await h.api().updateProjectDetails(projectDetailsValues);assert.equal(h.requests.length,0);},'useProjectWorkspace');
check('project details backend management permission does not additionally require execution-work permission',async h=>{h.permissions(['projects.manage']);readyDetail(h,'/edit');assert.equal(h.api().editorAllowed,true);await h.api().updateProjectDetails(projectDetailsValues);assert.equal(h.requests.filter(r=>r.options.method==='PATCH').length,1);},'useProjectWorkspace');
for(const [name,patch]of [['blank name',{name:'  '}],['long name',{name:'x'.repeat(221)}],['unknown priority',{priority:'invalid'}],['reversed dates',{planned_start_date:'2026-12-31',due_date:'2026-10-30'}]])check(`details editor blocks ${name} locally`,async h=>{readyDetail(h,'/edit');await h.api().updateProjectDetails({...projectDetailsValues,...patch});assert.equal(h.requests.length,0);},'useProjectWorkspace');
check('details unknown PATCH stays locked and keeps dirty draft after read refresh',async h=>{readyDetail(h,'/edit',{formDirty:true});h.response(()=>Promise.reject(new Error('Disconnected')));await h.api().updateProjectDetails(projectDetailsValues);assert.equal(h.state('unknownWrite'),true);assert.equal(h.state('formDirty'),true);h.response(h.defaultResponse);await h.api().refresh();h.render();await h.api().updateProjectDetails(projectDetailsValues);assert.equal(h.requests.filter(r=>r.options.method==='PATCH').length,1);assert.equal(h.state('documentCommitted'),false);},'useProjectWorkspace');
check('details 422 preserves editable form and renders readable validation',async h=>{readyDetail(h,'/edit',{formDirty:true});h.response(()=>fail(422,[{loc:['body','due_date'],msg:'Invalid date'}]));await h.api().updateProjectDetails(projectDetailsValues);assert.equal(h.state('unknownWrite'),false);assert.equal(h.state('formDirty'),true);assert.match(h.state('error'),/due_date: Invalid date/);assert.equal(h.navigation.length,0);},'useProjectWorkspace');
check('details pending duplicate and Cancel cannot send twice or leave before acknowledgment',async h=>{readyDetail(h,'/edit');let release;h.response(()=>new Promise(resolve=>{release=resolve;}));const first=h.api().updateProjectDetails(projectDetailsValues);h.render();await h.api().updateProjectDetails(projectDetailsValues);h.api().closeEditor();assert.equal(h.requests.length,1);assert.equal(h.navigation.length,0);release(ok(project));await first;assert.equal(h.state('documentCommitted'),true);},'useProjectWorkspace');
check('details dirty Cancel keeps fields and route without a mutation',h=>{readyDetail(h,'/edit',{formDirty:true});h.confirm(false);h.api().closeEditor();assert.equal(h.navigation.length,0);assert.equal(h.requests.length,0);},'useProjectWorkspace');
check('project details component has six labeled native fields and baseline values',h=>{const tree=h.component('src/components/projects/project-editors.tsx','ProjectDetailsEditor',{project,saving:false,onClose(){},onSave:async()=>{},onDirtyChange(){}});assert.equal(nodes(tree,'input').length,3);assert.equal(nodes(tree,'textarea').length,2);assert.equal(nodes(tree,'select').length,1);assert.equal(nodes(tree,'input')[0].props.maxLength,220);assert.equal(nodes(tree,'textarea')[1].props.value,'');assert.equal(nodes(tree,'EditorFrame')[0].props.disabled,false);});
check('project details form marks reversed schedule and disables Save',h=>{const tree=h.component('src/components/projects/project-editors.tsx','ProjectDetailsEditor',{project:{...project,planned_start_date:'2026-12-31',due_date:'2026-10-30'},saving:false,onClose(){},onSave:async()=>{},onDirtyChange(){}});assert.equal(nodes(tree,'EditorFrame')[0].props.disabled,true);assert.ok(text(tree).includes('Due date cannot be before planned start.'));});

// The actual Projects BFF preserves bytes; unlike the Accounting JSON BFF it
// does not synthesize the sentinel for malformed JSON. Cover both explicitly.
const {projectProxyFixture}=require('./helpers/project-proxy-fixture.cjs');
for(const [label,status,raw]of [
 ['null422',422,'null'],['unreadable422',422,'<broken>'],['blank422',422,JSON.stringify({detail:'   '})],
 ['sentinel422',422,JSON.stringify({detail:'Unexpected upstream response'})],['sentinel400',400,JSON.stringify({detail:' unexpected UPSTREAM response. '})],
 ['placeholder422',422,JSON.stringify({detail:'Project request failed.'})],['rate429',429,JSON.stringify({detail:'Synthetic rate limit'})],
 ['timeout408',408,JSON.stringify({detail:'Synthetic timeout'})],
])for(const mode of ['create','details'])check(`${mode} actual proxy ${label} freezes an unkeyed write and ignores repeated submit`,async h=>{
 if(mode==='create')readyCreate(h);else readyDetail(h,'/edit',{formDirty:true});
 h.response(()=>projectProxyFixture(status,raw));
 const submit=()=>mode==='create'?h.api().createProject():h.api().updateProjectDetails(projectDetailsValues);
 await submit();h.render();assert.equal(h.state('unknownWrite'),true);await submit();
 assert.equal(h.requests.filter(r=>['POST','PATCH'].includes(r.options?.method)).length,1);
 assert.equal(h.navigation.length,0);
},mode==='create'?'useProjectCreate':'useProjectWorkspace');
for(const detail of ['The due date must follow the start date',{message:'Project state changed; review it'},[{loc:['body','due_date'],msg:'Invalid date'}]])check('actual proxy valid corrective422 retains editable correction '+JSON.stringify(detail),async h=>{readyDetail(h,'/edit',{formDirty:true});h.response(()=>projectProxyFixture(422,JSON.stringify({detail})));await h.api().updateProjectDetails(projectDetailsValues);h.render();assert.equal(h.state('unknownWrite'),false);await h.api().updateProjectDetails(projectDetailsValues);assert.equal(h.requests.filter(r=>r.options?.method==='PATCH').length,2);assert.equal(h.navigation.length,0);},'useProjectWorkspace');
check('rejection certainty keeps reviewed corrective statuses but rejects empty placeholders and ambiguous statuses',h=>{const {projectRequestWasRejected:rejected}=h.load(path.join(root,'src/lib/project-request.ts'));for(const status of [400,401,403,404,405,409,410,413,415,422])assert.equal(rejected(status,{detail:{message:'Synthetic corrective error'}}),true);for(const status of [408,429,500,503])assert.equal(rejected(status,{detail:'Readable but uncertain'}),false);for(const payload of [null,{},[],{detail:' '},{message:' '},{detail:' Unexpected Upstream Response. '},{message:'Project request failed.'}])assert.equal(rejected(422,payload),false);});

check('actual unknown workspace renders one generic notice and retains the disabled editor',h=>{const {PROJECT_WRITE_UNKNOWN}=h.load(path.join(root,'src/lib/project-request.ts'));readyDetail(h,'/tasks/new',{unknownWrite:true,error:PROJECT_WRITE_UNKNOWN});const tree=h.component(detailFile,'ProjectWorkspaceContent',{}),notices=nodes(tree,'RelationshipNotice');assert.equal(notices.length,1);assert.equal(text(notices[0]),'The save result is uncertain. Submitting again is blocked. Return to the project and review the latest records before starting another change.');assert.equal(nodes(tree,'fieldset')[0].props.disabled,true);assert.equal(nodes(tree,'ProjectEditor').length,1);},'useProjectWorkspace');
check('actual unknown workspace preserves a distinct read error rather than hiding all errors',h=>{readyDetail(h,'/tasks/new',{unknownWrite:true,error:'Synthetic register read unavailable'});const tree=h.component(detailFile,'ProjectWorkspaceContent',{});assert.equal(nodes(tree,'RelationshipNotice').length,2);assert.match(text(tree),/Synthetic register read unavailable/);assert.equal(nodes(tree,'fieldset')[0].props.disabled,true);},'useProjectWorkspace');
check('generic error remains visible if no unknown latch is present',h=>{const {PROJECT_WRITE_UNKNOWN}=h.load(path.join(root,'src/lib/project-request.ts'));readyDetail(h,'/tasks/new',{unknownWrite:false,error:PROJECT_WRITE_UNKNOWN});const tree=h.component(detailFile,'ProjectWorkspaceContent',{});assert.equal(nodes(tree,'RelationshipNotice').length,1);assert.equal(text(nodes(tree,'RelationshipNotice')[0]),PROJECT_WRITE_UNKNOWN);},'useProjectWorkspace');
check('unknown credential editor retains safe specific detail inline and its locked boundary',h=>{const detail='Credentials Vault is temporarily unavailable. Please contact your administrator.';readyDetail(h,'/credentials/new',{unknownWrite:true,credentialError:detail});const tree=h.component(detailFile,'ProjectWorkspaceContent',{});assert.equal(nodes(tree,'RelationshipNotice').length,1);assert.equal(nodes(tree,'fieldset')[0].props.disabled,true);const editor=nodes(tree,'ProjectEditor')[0];const rendered=h.component('src/components/projects/project-editors.tsx','ProjectEditor',editor.props);assert.equal(nodes(rendered,'CredentialEditor')[0].props.error,detail);const child=harness();try{const credentialTree=child.component('src/components/projects/project-editors.tsx','CredentialEditor',nodes(rendered,'CredentialEditor')[0].props);assert.match(text(credentialTree),/Credentials Vault is temporarily unavailable/);}finally{child.cleanup();}},'useProjectWorkspace');
check('unknown noneditor credential error remains a separate specific notice',h=>{readyDetail(h,'',{unknownWrite:true,credentialError:'Synthetic safe Vault detail'});const tree=h.component(detailFile,'ProjectWorkspaceContent',{});assert.equal(nodes(tree,'RelationshipNotice').length,2);assert.match(text(tree),/Synthetic safe Vault detail/);},'useProjectWorkspace');

for(const [environment,credentialType] of [['test','custom_token'],['QA বাংলা','Custom API']])check(`saved custom credential values render selected and save unchanged: ${environment}`,h=>{
 const saved=[],f=form(h,'CredentialEditor',{credential:{...credential,environment,credential_type:credentialType},onSave:value=>saved.push(value)});
 const tree=f.render(),selects=nodes(tree,'select');
 for(const [label,value] of [['Environment',environment],['Credential type',credentialType]]){
  const select=selects.find(node=>node.props['aria-label']===label);assert.ok(select);assert.equal(select.props.value,value);
  assert.equal(nodes(select,'option').filter(option=>option.props.value===value).length,1);
  const html=require('react-dom/server').renderToStaticMarkup(select);
  assert.ok(html.includes(`value="${value}" selected=""`),html);
 }
 tree.props.onSave();assert.equal(saved[0].environment,environment);assert.equal(saved[0].credential_type,credentialType);assert.equal(saved[0].secret,'');assert.equal(h.requests.length,0);
 assert.deepEqual(selects.at(-1).props.children.map(node=>node.props.value),['manager_only','team']);
});
check('saved custom credential remains selectable after an explicit canonical choice',h=>{
 const saved=[],f=form(h,'CredentialEditor',{credential:{...credential,environment:'test',credential_type:'custom_token'},onSave:value=>saved.push(value)});
 let tree=f.render();nodes(tree,'select').find(node=>node.props['aria-label']==='Environment').props.onChange({target:{value:'staging'}});
 nodes(tree,'select').find(node=>node.props['aria-label']==='Credential type').props.onChange({target:{value:'api_key'}});
 tree=f.render();tree.props.onSave();assert.equal(saved[0].environment,'staging');assert.equal(saved[0].credential_type,'api_key');
 const env=nodes(tree,'select').find(node=>node.props['aria-label']==='Environment');assert.ok(nodes(env,'option').some(node=>node.props.value==='test'));
 env.props.onChange({target:{value:'test'}});tree=f.render();tree.props.onSave();assert.equal(saved[1].environment,'test');assert.equal(h.requests.length,0);
});
for(const existing of [null,credential])check(`canonical credential options and creation defaults are unchanged: ${existing?'edit':'new'}`,h=>{
 const tree=form(h,'CredentialEditor',{credential:existing}).render(),selects=nodes(tree,'select');
 const env=selects.find(node=>node.props['aria-label']==='Environment'),type=selects.find(node=>node.props['aria-label']==='Credential type');
 assert.deepEqual(nodes(env,'option').map(node=>node.props.value),['production','staging','development','other']);
 assert.deepEqual(nodes(type,'option').map(node=>node.props.value),['login','api_key','database','ssh','hosting','domain','other']);
 assert.equal(env.props.value,existing?'development':'production');assert.equal(type.props.value,'login');assert.equal(h.requests.length,0);
});
for(const [field,label,values] of [['credential_type','Credential type',['login','api_key','database','ssh','hosting','domain','other']],['environment','Environment',['production','staging','development','other']]])for(const value of values)check(`each canonical ${field} has exactly one selected option: ${value}`,h=>{
 const tree=form(h,'CredentialEditor',{credential:{...credential,[field]:value}}).render(),select=nodes(tree,'select').find(node=>node.props['aria-label']===label);
 assert.equal(select.props.value,value);assert.equal(nodes(select,'option').length,values.length);assert.equal(nodes(select,'option').filter(node=>node.props.value===value).length,1);
 assert.ok(require('react-dom/server').renderToStaticMarkup(select).includes(`value="${value}" selected=""`));assert.equal(h.requests.length,0);
});
